const item = $input.first().json;
const base = $env.KANALLAR_BASE_URL || '';
const src = $('When called by another workflow').first().json;
const preview = `${base}/media/${src.video_id}`;
const msg = [
  `VIDEO ONAY`,
  `Kanal: ${src.channel_id || ''}`,
  `Topic: ${src.topic || ''}`,
  `Title: ${src.title || ''}`,
  `Preview: ${preview}`,
  `Studio: ${base}/`,
  '',
  `PUBLISH | REVISE | REJECT`,
  `Token: ${item.token}`
].join('\n');
return [{ json: { ...item, ...src, preview_url: preview, telegram_text: msg } }];
